mapper.select:
SELECT a.group_id FROM t_activity a
JOIN t_group_player g ON g.group_id = a.group_id
WHERE a.activity_id = #{activityId} AND a.level = 302 AND a.status IN (0,1) AND g.ower_id = #{uid}

SELECT a.*, z.player_id playerId, COUNT(z.id) round, SUM(z.play_point_count) score FROM t_activity a INNER JOIN t_group_zhanji z ON a.activity_id=z.activity_id WHERE a.activity_id IN ( SELECT activity_id FROM t_group_zhanji WHERE group_id=#{groupId}
AND player_id=#{playerId}
)
AND DATE_FORMAT(a.create_date,'%Y-%m-%d')=#{dateStr}
AND z.player_id=#{playerId}
GROUP BY z.id LIMIT #{pageIndex}, #{pageSize}
